import math, collections
def H1(s):
    # order-1 conditional entropy in bits
    d=collections.defaultdict(collections.Counter)
    for a,b in zip(s,s[1:]):
        d[a][b]+=1
    tot=0
    for a,c in d.items():
        n=sum(c.values())
        for b,k in c.items():
            tot -= k*math.log2(k/n)
    return tot
def H0(s):
    c=collections.Counter(s); n=len(s)
    return -sum(k*math.log2(k/n) for k in c.values())
